        d=ar['locales'][LANG];sections=ARTICLE_SECTIONS[i];file='insight-'+ar['slug']+'.html'
        words=' '.join(d['opening']+[t(s[1]) for s in sections]).split();mins=max(3,math.ceil(len(words)/180))
        body=hero(t(P('FIELD NOTES','PRAXISEINBLICKE')),d['title'],d['intro'],('insights.html',t(P('All insights','Alle Einblicke'))))
        body+='<div class="wrap article-meta"><span>'+tx('By MuJobs','Von MuJobs')+'</span><span>'+str(mins)+' '+tx('min read','Min. Lesezeit')+'</span><span>'+tx('Recruitment practice','Recruiting-Praxis')+'</span></div><div class="wrap reading-layout"><aside class="contents"><span class="eyebrow">'+tx('IN THIS ARTICLE','IN DIESEM ARTIKEL')+'</span>'+''.join(f'<a href="#part-{j}">{e(t(s[0]))}</a>' for j,s in enumerate(sections))+'</aside><article class="reading"><section class="article-opening">'+''.join(p(x) for x in d['opening'])+'</section>'
        for j,(head,para) in enumerate(sections):body+=f'<section id="part-{j}"><span class="eyebrow">0{j+1}</span><h2>{e(t(head))}</h2>'+p(t(para))+'</section>'
        body+='<aside class="takeaway"><span class="eyebrow">'+tx('PUT IT INTO PRACTICE','IN DIE PRAXIS ÜBERTRAGEN')+'</span><h2>'+tx('Bring one live role to the conversation.','Bringen Sie eine konkrete Rolle mit.')+'</h2>'+p(t(P('Take the questions in this article and apply them to the position you are trying to fill. Write down what is known, what is assumed and which conversation would resolve the most important uncertainty. A clearer brief is a practical first step towards a more relevant search.','Übertragen Sie die Fragen dieses Artikels auf Ihre offene Position. Notieren Sie, was bekannt ist, was angenommen wird und welches Gespräch die wichtigste Unsicherheit klären kann. Ein genaueres Profil ist ein praktischer erster Schritt zu einer passenderen Suche.')))+a('work.html',t(P('See how this looks in practice','Beispiele aus der Praxis')),'text-link')+'</aside></article></div>'
        body+='<section class="wrap section"><div class="section-heading"><span class="eyebrow">'+tx('CONTINUE READING','WEITERLESEN')+'</span><h2>'+tx('Another angle on hiring.','Ein weiterer Blick auf Recruiting.')+'</h2></div>'+insight_card(articles[(i+1)%len(articles)],(i+1)%len(articles))+'</section>'+cta()
        schema={'@context':'https://schema.org','@type':'Article','headline':d['title'],'description':d['intro'],'inLanguage':LANG,'author':{'@type':'Organization','name':'MuJobs','url':BASE},'publisher':{'@type':'Organization','name':'MuJobs'},'mainEntityOfPage':BASE+url(file),'wordCount':len(words)}
        page(file,d['title'].rstrip('.')+' | MuJobs',d['intro'],body,'article',schema)
